// Lightweight canvas confetti engine
(function(window) {
  function ConfettiGenerator() {
    var canvas = null;
    var ctx = null;
    var particles = [];
    var animationId = null;

    function getCanvas() {
      if (!canvas) {
        canvas = document.createElement('canvas');
        canvas.style.position = 'fixed';
        canvas.style.top = '0';
        canvas.style.left = '0';
        canvas.style.width = '100vw';
        canvas.style.height = '100vh';
        canvas.style.pointerEvents = 'none';
        canvas.style.zIndex = '99999';
        document.body.appendChild(canvas);
        ctx = canvas.getContext('2d');
        resize();
        window.addEventListener('resize', resize);
      }
      return canvas;
    }

    function resize() {
      if (canvas) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }
    }

    function randomRange(min, max) {
      return Math.random() * (max - min) + min;
    }

    var colors = ['#06b6d4', '#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#8b5cf6', '#ffffff'];

    window.confetti = function(opts) {
      opts = opts || {};
      var count = opts.particleCount || 80;
      var originY = opts.origin && opts.origin.y !== undefined ? opts.origin.y : 0.6;
      getCanvas();

      var startX = window.innerWidth / 2;
      var startY = window.innerHeight * originY;

      for (var i = 0; i < count; i++) {
        var angle = randomRange(-Math.PI * 0.8, -Math.PI * 0.2);
        var speed = randomRange(10, 24);
        particles.push({
          x: startX,
          y: startY,
          vx: Math.cos(angle) * speed + randomRange(-4, 4),
          vy: Math.sin(angle) * speed,
          size: randomRange(6, 12),
          color: colors[Math.floor(Math.random() * colors.length)],
          rotation: randomRange(0, 360),
          rotationSpeed: randomRange(-12, 12),
          gravity: 0.5,
          drag: 0.96,
          opacity: 1,
          decay: randomRange(0.008, 0.02)
        });
      }

      if (!animationId) {
        loop();
      }
    };

    function loop() {
      if (!ctx || !canvas) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      for (var i = particles.length - 1; i >= 0; i--) {
        var p = particles[i];
        p.vx *= p.drag;
        p.vy *= p.drag;
        p.vy += p.gravity;
        p.x += p.vx;
        p.y += p.vy;
        p.rotation += p.rotationSpeed;
        p.opacity -= p.decay;

        if (p.opacity <= 0 || p.y > canvas.height + 50) {
          particles.splice(i, 1);
          continue;
        }

        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate((p.rotation * Math.PI) / 180);
        ctx.globalAlpha = Math.max(0, p.opacity);
        ctx.fillStyle = p.color;
        ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size * 0.6);
        ctx.restore();
      }

      if (particles.length > 0) {
        animationId = requestAnimationFrame(loop);
      } else {
        cancelAnimationFrame(animationId);
        animationId = null;
        if (canvas && canvas.parentNode) {
          canvas.parentNode.removeChild(canvas);
          canvas = null;
          ctx = null;
        }
      }
    }
  }

  ConfettiGenerator();
})(window);
